assertion.value:
if (!context.prompt.label?.includes('gated')) return true;
const result = JSON.parse(output);
return Array.isArray(result.rejected_urls) && result.rejected_urls.some((url) => /forbes|tradewindai|defensescoop|swarmforge\.ai/.test(url));

